python3 << 'PYEOF'
import json

g = json.load(open('/Users/dm/orca/workspaces/HarnessHub/wt-32/eval-log/dev-graph/live-trial-fixtures/20260802-wt32-requirements-postmain/.dev-graph/state/graph.json'))

# C11 report says: implementation_readiness=complete, valid=true, 0 violations
# Verify each node in lineage closure has consistent readiness
closure_ids = ['F-LIVE-001','LT-ARCH-001'] + [f'SYS-LIVE-001-P{i:02d}' for i in range(1,14)]
issues = []
for n in g['nodes']:
    nid = n['graph_node_id']
    if nid in closure_ids:
        ir = n.get('implementation_readiness', {})
        es = n.get('evaluation_status')
        cs = n.get('confirmation_status')
        status = n.get('status')
        ir_status = ir.get('status') if isinstance(ir, dict) else ir
        missing = ir.get('missing_sections', []) if isinstance(ir, dict) else []
        if es != 'pass':
            issues.append(f'{nid}: evaluation_status={es}')
        if cs != 'confirmed':
            issues.append(f'{nid}: confirmation_status={cs}')
        if ir_status not in ('complete', None):
            issues.append(f'{nid}: implementation_readiness={ir_status}')
        if missing:
            issues.append(f'{nid}: missing_sections={missing}')
        if status != 'active':
            issues.append(f'{nid}: status={status}')

if issues:
    print('ISSUES FOUND:')
    for i in issues:
        print(f'  - {i}')
else:
    print('ALL NODES CONSISTENT: evaluation_status=pass, confirmation_status=confirmed, no missing sections')
PYEOF

